To solve this problem using Scala, you can use a backtracking algorithm to generate all possible permutations of the numbers 1 to 9 and check if they meet the given constraints. Here's a possible implementation:
```scala
import scala.collection.mutable.ListBuffer
object MagicSquare {
  val PRIMES = Set(2, 3, 5, 7)
  val COMPOSITES = Set(4, 6, 8)
  def main(args: Array[String]): Unit = {
    val solutions = ListBuffer.empty[Array[Int]]
    val nums = (1 to 9).toArray
    permute(nums, 0, solutions)
    solutions.foreach(printSolution)
  }
  def permute(nums: Array[Int], start: Int, solutions: ListBuffer[Array[Int]]): Unit = {
    if (start == nums.length) {
      if (isValidSolution(nums)) {
        solutions += nums.clone()
      }
    } else {
      for (i <- start until nums.length) {
        swap(nums, start, i)
        permute(nums, start + 1, solutions)
        swap(nums, start, i)
      }
    }
  }
  def isValidSolution(nums: Array[Int]): Boolean = {
    val sum = nums.slice(0, 3).sum
    // check rows
    for (i <- 0 to 6 by 3) {
      if (nums.slice(i, i + 3).sum != sum) {
        return false
      }
    }
    // check columns
    for (i <- 0 to 2) {
      if (nums(i) + nums(i + 3) + nums(i + 6) != sum) {
        return false
      }
    }
    // check diagonals
    if (nums(0) + nums(4) + nums(8) != sum || nums(2) + nums(4) + nums(6) != sum) {
      return false
    }
    // check center square
    if (!PRIMES.contains(nums(4)) || nums.slice(0, 3).intersect(COMPOSITES).nonEmpty ||
        nums.slice(6, 9).intersect(COMPOSITES).nonEmpty || nums(1) % 2 != 0 || nums(7) % 2 != 0) {
      return false
    }
    true
  }
  def swap(nums: Array[Int], i: Int, j: Int): Unit = {
    val temp = nums(i)
    nums(i) = nums(j)
    nums(j) = temp
  }
  def printSolution(nums: Array[Int]): Unit = {
    for (i <- 0 to 6 by 3) {
      println(nums.slice(i, i + 3).mkString(" "))
    }
    println()
  }
}
```
The `permute` function generates all possible permutations of the input array `nums` using a recursive backtracking algorithm. The `isValidSolution` function checks if a given permutation satisfies the constraints of the problem. The `swap` function is a helper function for swapping elements in the array. Finally, the `printSolution` function prints a valid solution to the console.
To run the program, simply call the `main` function. The program will print all valid solutions to the console. Note that there are multiple valid solutions to this problem, so the program may take some time to run.

