```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.Linq;
class Program
{
    static void Main(string[] args)
    {
        string xml = @"<cars>
                            <car>
                                <name>Ferrari</name>
                                <price>350000</price>
                            </car>
                            <car>
                                <name>Lamborghini</name>
                                <price>300000</price>
                            </car>
                            <car>
                                <name>Porsche</name>
                                <price>250000</price>
                            </car>
                            <car>
                                <name>Audi</name>
                                <price>200000</price>
                            </car>
                            <car>
                                <name>Mercedes</name>
                                <price>150000</price>
                            </car>
                        </cars>";
        XDocument doc = XDocument.Parse(xml);
        var cars = doc.Descendants("car")
                    .Select(c => new {
                        Name = c.Element("name").Value,
                        Price = int.Parse(c.Element("price").Value)
                    })
                    .OrderByDescending(c => c.Price);
        Console.WriteLine("<table>");
        Console.WriteLine("<tr><th>Name</th><th>Price</th></tr>");
        foreach (var car in cars)
        {
            Console.WriteLine("<tr><td>{0}</td><td>{1:C}</td></tr>", car.Name, car.Price);
        }
        Console.WriteLine("</table>");
    }
}
```
This code first parses the XML string and creates a list of anonymous objects with the car name and price. It then sorts the list by price in descending order and outputs the results to an HTML table. The `Console.WriteLine` statements can be replaced with code that generates the HTML table and writes it to a file or sends it to a web browser.

