```swift
import Foundation
// Generate a random number between 1 and 100
let randomNumber = Int.random(in: 1...100)
// Initialize the number of guesses to 0
var numGuesses = 0
// Loop until the user guesses the correct number
while true {
    // Prompt the user to input their guess
    print("Guess a number between 1 and 100:")
    let guess = Int(readLine()!)!

    // Increment the number of guesses
    numGuesses += 1

    // Check if the guess matches the random number
    if guess == randomNumber {
        print("Congratulations, you guessed the number in \(numGuesses) guesses!")
        break
    } else if guess < randomNumber {
        print("Too low, try again.")
    } else {
        print("Too high, try again.")
    }
}
// Connect to the SQL database
import MySQL
let mysql = MySQL()
mysql.connect(host: "localhost", user: "root", password: "password", database: "mydatabase")
// Insert the user's guesses and results into the database
let insertQuery = "INSERT INTO guesses (guess, result) VALUES (\(guess), \(numGuesses))"
mysql.query(insertQuery)
```
