using System;
using System.Security.Cryptography;
using System.IO;
public static class EncryptionHelper
{
    private static readonly byte[] salt = Encoding.ASCII.GetBytes("Insert your salt here");
    public static void EncryptFile(string inputFile, string outputFile, string password)
    {
        byte[] passwordBytes = Encoding.ASCII.GetBytes(password);
        byte[] saltBytes = salt;
        byte[] encryptedBytes = null;
        using (MemoryStream ms = new MemoryStream())
        {
            using (RijndaelManaged AES = new RijndaelManaged())
            {
                AES.KeySize = 256;
                AES.BlockSize = 128;
                var key = new Rfc2898DeriveBytes(passwordBytes, saltBytes, 1000);
                AES.Key = key.GetBytes(AES.KeySize / 8);
                AES.IV = key.GetBytes(AES.BlockSize / 8);
                AES.Mode = CipherMode.CFB;
                using (var cs = new CryptoStream(ms, AES.CreateEncryptor(), CryptoStreamMode.Write))
                {
                    using (var inputFileStream = new FileStream(inputFile, FileMode.Open))
                    {
                        inputFileStream.CopyTo(cs);
                    }
                }
                encryptedBytes = ms.ToArray();
            }
        }
        File.WriteAllBytes(outputFile, encryptedBytes);
    }
    public static void DecryptFile(string inputFile, string outputFile, string password)
    {
        byte[] passwordBytes = Encoding.ASCII.GetBytes(password);
        byte[] saltBytes = salt;
        byte[] decryptedBytes = null;
        using (MemoryStream ms = new MemoryStream())
        {
            using (RijndaelManaged AES = new RijndaelManaged())
            {
                AES.KeySize = 256;
                AES.BlockSize = 128;
                var key = new Rfc2898DeriveBytes(passwordBytes, saltBytes, 1000);
                AES.Key = key.GetBytes(AES.KeySize / 8);
                AES.IV = key.GetBytes(AES.BlockSize / 8);
                AES.Mode = CipherMode.CFB;
                using (var cs = new CryptoStream(ms, AES.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    using (var inputFileStream = new FileStream(inputFile, FileMode.Open))
                    {
                        inputFileStream.CopyTo(cs);
                    }
                }
                decryptedBytes = ms.ToArray();
            }
        }
        File.WriteAllBytes(outputFile, decryptedBytes);
    }
}
```
