using System;
using System.Net.Http;
using System.Text;
using Newtonsoft.Json;
class Program
{
    static async Task Main(string[] args)
    {
        var text = "I love this product!";
        var apiKey = "YOUR_API_KEY";
        var endpoint = "https://YOUR_ENDPOINT.cognitiveservices.azure.com/text/analytics/v3.0-preview.1/sentiment";
        var requestBody = new
        {
