To solve the equation x^3 - 4x^2 + 5x - 2 = 0 using C++, you can use the Newton-Raphson method. Here's the code:
```
#include <iostream>
#include <cmath>
using namespace std;
double f(double x) {
    return pow(x, 3) - 4 * pow(x, 2) + 5 * x - 2;
}
double f_prime(double x) {
    return 3 * pow(x, 2) - 8 * x + 5;
}
double newton_raphson(double x) {
    double epsilon = 0.0001;
    double fx = f(x);
    while (abs(fx) > epsilon) {
        double fpx = f_prime(x);
        if (fpx == 0) {
            cout << "Error: division by zero" << endl;
            return 0;
        }
        x = x - fx / fpx;
        fx = f(x);
    }
    return x;
}
int main() {
    double x0 = 1.0;
    double root = newton_raphson(x0);
    cout << "The root is: " << root << endl;
    return 0;
}
```
