```go
package main
import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"strings"
)
type City struct {
	Name          string  `json:"city"`
	CostOfLiving  float64 `json:"cost_of_living_index"`
}
func main() {
	// Retrieve top 10 most expensive cities from Numbeo API
	resp, err := http.Get("https://www.numbeo.com/api/rankings_by_city_current?api_key=<YOUR_API_KEY>&section=1")
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	defer resp.Body.Close()
	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	var cities []City
	err = json.Unmarshal(body, &cities)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	// Calculate average number of vowels in city names
	totalVowels := 0
	for i := 0; i < 10; i++ {
		name := cities[i].Name
		vowels := 0
		for _, c := range strings.ToLower(name) {
			switch c {
			case 'a', 'e', 'i', 'o', 'u':
				vowels++
			}
		}
		totalVowels += vowels
	}
	avgVowels := float64(totalVowels) / 10.0
	fmt.Printf("The average number of vowels in the names of the top 10 most expensive cities is %.2f\n", avgVowels)
}
