Here is an example code for implementing a feedforward neural network in C++ using the TensorFlow library:
// Define the neural network model
tensorflow::Scope root = tensorflow::Scope::NewRootScope();
tensorflow::Output x = Placeholder(root, DT_FLOAT, Placeholder::Shape({1, num_inputs}));
tensorflow::Output y = Placeholder(root, DT_FLOAT, Placeholder::Shape({1, num_outputs}));
tensorflow::Output w1 = Variable(root, {num_inputs, num_hidden}, DT_FLOAT);
tensorflow::Output b1 = Variable(root, {num_hidden}, DT_FLOAT);
tensorflow::Output w2 = Variable(root, {num_hidden, num_outputs}, DT_FLOAT);
tensorflow::Output b2 = Variable(root, {num_outputs}, DT_FLOAT);
tensorflow::Output h = Relu(root, Add(root, MatMul(root, x, w1), b1));
tensorflow::Output output = Add(root, MatMul(root, h, w2), b2);
tensorflow::Output loss = Mean(root, SquaredDifference(root, output, y), {0, 1});
// Train the model using gradient descent
tensorflow::ClientSession session(root);
tensorflow::OptimizerOptions options;
options.set_learning_rate(0.01);
tensorflow::GradientDescentOptimizer optimizer(root, options);
tensorflow::Session::FeedDict feed_dict = {{x, input_data}, {y, output_data}};
for (int i = 0; i < num_epochs; i++) {
  session.Run(feed_dict, {loss}, {}, &loss_value);
  session.Run(feed_dict, {optimizer.minimize(loss)}, {});
}
